#!/usr/bin/env node
/**
 * Build-time config injection for the Cloudflare Pages Functions.
 *
 * The functions in functions/api/ are bundled separately from the Astro build
 * and CANNOT import site.config.json at runtime — which is why lead.js used to
 * hardcode LEAD_SOURCE and had no way to read a per-client timezone at all. This
 * script closes that seam: it reads site.config.json and writes a small
 * generated module the functions DO import, so the two can never drift.
 *
 * Runs in `prebuild`/`build` and before every deploy. The generated file is
 * gitignored — it is build output, regenerated from config, never hand-edited.
 *
 * FAIL LOUD, don't default. site.timeZone drives the lead-summary block's local
 * times; a wrong or absent zone renders the wrong time to a crew reading it in a
 * truck. Per the extraction plan (Phase 1b) the value is required — we throw
 * rather than silently falling back to UTC.
 */

import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const CONFIG = resolve(ROOT, 'site.config.json');
const OUT = resolve(ROOT, 'functions/api/_config.generated.js');

const config = JSON.parse(readFileSync(CONFIG, 'utf8'));
const site = config.site || {};

const timeZone = String(site.timeZone || '').trim();
if (!timeZone) {
  console.error(
    '\x1b[31m[gen-function-config]\x1b[0m site.config.json → site.timeZone is unset.\n' +
      '  It is required: the lead-summary block renders local times, and defaulting\n' +
      '  to UTC would show the wrong time to whoever reads the lead. Set it to an IANA\n' +
      '  zone (e.g. "America/New_York", "America/Indiana/Indianapolis").'
  );
  process.exit(1);
}

// Validate it is a real IANA zone rather than a typo that silently degrades.
try {
  new Intl.DateTimeFormat('en-US', { timeZone });
} catch {
  console.error(`\x1b[31m[gen-function-config]\x1b[0m site.timeZone "${timeZone}" is not a valid IANA time zone.`);
  process.exit(1);
}

const banner =
  '// AUTO-GENERATED by scripts/gen-function-config.mjs from site.config.json.\n' +
  '// Do not edit — regenerate with `npm run config:gen`. Gitignored on purpose.\n';

const body =
  banner +
  'export const SITE = ' +
  JSON.stringify(
    {
      timeZone,
      leadSource: String(site.leadSource || '').trim(),
      leadTag: String(site.leadTag || '').trim(),
    },
    null,
    2,
  ) +
  ';\n';

writeFileSync(OUT, body);
console.log(`\x1b[32m[gen-function-config]\x1b[0m wrote functions/api/_config.generated.js (timeZone=${timeZone})`);
